 1	final class BinarySearch {
 2	    private static final int NOT_FOUND = -1;
 3	
 4	    private BinarySearch() {
 5	    }
 6	
 7	    static int binarySearch(int[] array, int target) {
 8	        return indexOf(array, target);
 9	    }
10	
11	    static int indexOf(int[] array, int target) {
12	        int low = 0;
13	        int high = array.length - 1;
14	
15	        while (low <= high) {
16	            int mid = midpoint(low, high);
17	            int value = array[mid];
18	
19	            if (value == target) {
20	                return mid;
21	            }
22	
23	            if (value < target) {
24	                low = mid + 1;
25	            } else {
26	                high = mid - 1;
27	            }
28	        }
29	
30	        return NOT_FOUND;
31	    }
32	
33	    static boolean isFound(int result) {
34	        return result != NOT_FOUND;
35	    }
36	
37	    private static int midpoint(int low, int high) {
38	        return low + (high - low) / 2;
39	    }
40	
